code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    fill = Counter(value for row in grid for value in row if value != 0).most_common(1)[0][0]

    # First look for a repeating pattern running along down-right diagonals.
    for period in range(1, min(h, w) + 1):
        bands = {}
        valid = True
        for r in range(h):
            for c in range(w):
                value = grid[r][c]
                if value == 0:
                    continue
                phase = (c - r) % period
                if phase in bands and bands[phase] != value:
                    valid = False
                    break
                bands[phase] = value
            if not valid:
                break
        if valid:
            return [[grid[r][c] if grid[r][c] != 0 else bands.get((c - r) % period, fill)
                     for c in range(w)] for r in range(h)]

    # Otherwise infer the smallest rectangular repeating tile.
    periods = sorted(((rh * cw, rh + cw, rh, cw)
                      for rh in range(1, h + 1)
                      for cw in range(1, w + 1)))
    for _, _, rh, cw in periods:
        tile = {}
        valid = True
        for r in range(h):
            for c in range(w):
                value = grid[r][c]
                if value == 0:
                    continue
                key = (r % rh, c % cw)
                if key in tile and tile[key] != value:
                    valid = False
                    break
                tile[key] = value
            if not valid:
                break
        if valid:
            return [[grid[r][c] if grid[r][c] != 0 else tile.get((r % rh, c % cw), fill)
                     for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
'''
